def get_mtype_in_section(possible_m_types, section):
    """
    Gets message type name e.g. "UL-CCCH-Message" from sections as in seciton example string
    """
    found_mptype = None
    for m_type in possible_m_types:
        if re.search('^{}\s+'.format(m_type), section):
            if found_mptype is None:
                found_mptype = m_type
            else:
                print('ERROR: Ambigous mtype found, had: {}, found: {}'.format(found_mptype, m_type))
    return found_mptype


def get_message_type_suffix(m_type):
    """
    Find suffis of message type. E.g. for "UL-CCCH-Message-NB" suffix is "NB"
    """
    return re.findall('-(\w+)$', m_type)[0]


def parse_nr_rrc():
    '''
        Parse 3GPP 38.331 standard and return dict mapping between message types and message choice
        '''
    message_types_from_standard = ['BCCH-BCH-MessageType',
                                   'BCCH-DL-SCH-MessageType',
                                   'PCCH-MessageType',
                                   'DL-CCCH-MessageType',
                                   'DL-DCCH-MessageType',
                                   'UL-CCCH-MessageType',
                                   'UL-CCCH1-MessageType',
                                   'UL-DCCH-MessageType'
                                   ]
    rrc_items = {}
    with open(os.path.join(os.path.dirname(__file__), 'asn_standard', 'nr_rrc.txt'), 'r') as f:
        message_type_data = f.read()
    sib_data = re.findall('SystemInformation\s*message\s*--\s*ASN1START(.*?)ASN1STOP', message_type_data,
                          re.MULTILINE | re.DOTALL)
    sib_data = "".join(sib_data)
    # pprint.pprint(sib_data)
    # message_type_data = re.sub('\s3GPP\s3GPP.*?\)\s', "", message_type_data)
    message_type_data = re.findall('(?:NR)-RRC-Definitions DEFINITIONS AUTOMATIC TAGS(.*?)6\.\d+\.\d+',
                                   message_type_data, re.MULTILINE | re.DOTALL)
    message_type_data = "".join(message_type_data)
    # print message_type_data
    message_type_data_lines = re.findall('(\S*MessageType\S*\s*::=.*?)\-\- ASN1STOP', message_type_data,
                                         re.DOTALL | re.MULTILINE)
    # pprint.pprint(message_type_data_lines)
    # check if all MessageTypes are parsed out from 3gpp
    for mtype in message_types_from_standard:
        found = False
        for message_type_data in message_type_data_lines:
            if mtype in message_type_data:
                found = True
                break
        assert found is True, 'no message_type_data for {}'.format(mtype)
    assert len(message_types_from_standard) == len(message_type_data_lines), \
        'length of parsed message_type_data does not match static message_types_from_standard length'
    for section in message_type_data_lines:
        _parse_nr_rrc_section(message_types_from_standard, rrc_items, section)
    sib_data_parsed = re.findall('OF CHOICE\s*\{(.*?)\}', sib_data, re.MULTILINE | re.DOTALL)
    # pprint.pprint(sib_data_parsed)
    for item in sib_data_parsed:
        item = re.sub(',\s*\.\.\.', '', item)
        item = item.split(',')
        # item = re.findall('OF CHOICE \{(.*?)\}', item, re.DOTALL)[0].split(',')
        for subitem in item:
            # pprint.pprint(subitem)
            subitem = re.findall('(\S+)', subitem)
            # pprint.pprint(subitem)
            rrc_items[subitem[0]] = subitem[1]
    pprint.pprint("NR-RRC Number of 3GPP compliant messages: {}".format(len(rrc_items)))
    # pprint.pprint(rrc_items)
    # pprint.pprint(rrc_non_3gpp_compliant_messages)
    # pprint.pprint(len(rrc_items))
    return rrc_items


def _parse_nr_rrc_section(message_types_from_standard, rrc_items, section):
    if 'CHOICE' in section:
        # if 'UL-CCCH-MessageType' in item:
        #     print(item)
        # for all c1,c2... items
        item = re.findall('c\d+\s*CHOICE\s*\{(.*?)\}', section, re.DOTALL | re.MULTILINE)
        # print(item)
        for sub_c_item in item:
            # pprint.pprint(subcitem)
            for subitem in sub_c_item.split(','):
                subitem = re.findall('(\S+)', subitem)
                if subitem[1] != 'NULL':
                    if subitem[0] in rrc_items:
                        # print(
                        #     'Trying to add: {}:{}, already exists {}:{}'.format(subitem[0], subitem[1], subitem[0],
                        #                                                         rrc_items[subitem[0]]))
                        mtype = get_mtype_in_section(message_types_from_standard, section)
                        # print('Found mtype: {}'.format(mtype))
                        m_type_suffix = get_message_type_suffix(mtype)
                        # print('Found mtype suffix: {}'.format(m_type_suffix))
                        new_subitem_0 = "{}-{}".format(subitem[0], m_type_suffix)
                        # print('Adding mtype_suffix: {} -> {} to differentiate'.format(subitem[0], new_subitem_0))
                        rrc_items[new_subitem_0] = subitem[1]

                    else:
                        # if 'BCCH-DL-SCH-MessageType' in section:
                        #     print subitem[0], subitem[1]
                        rrc_items[subitem[0]] = subitem[1]
        else:
            # for MasterInformationBlock\S*
            for line in section.split('\n'):
                # print('$'+line+'$')
                res = re.search('(\S+)\s+(\S+)\,', line)
                if res:
                    # print('found')
                    non_3gpp = res.group(1)
                    name_3gpp = res.group(2)
                    # # print item
                    rrc_items[non_3gpp] = name_3gpp


def parse_rrc():
    '''
    Parse 3GPP 36.331 standard and return dict mapping between message types and message choice
    '''
    message_types_from_standard = ['BCCH-BCH-MessageType',
                                   'BCCH-BCH-MessageType-NB',
                                   'BCCH-BCH-MessageType-MBMS-r14',
                                   'BCCH-DL-SCH-MessageType',
                                   'BCCH-DL-SCH-MessageType-BR-r13',
                                   'BCCH-DL-SCH-MessageType-NB',
                                   'BCCH-DL-SCH-MessageType-MBMS-r14',
                                   'MCCH-MessageType',
                                   'PCCH-MessageType',
                                   'PCCH-MessageType-NB',
                                   'DL-CCCH-MessageType',
                                   'DL-CCCH-MessageType-NB',
                                   'DL-DCCH-MessageType',
                                   'DL-DCCH-MessageType-NB',
                                   'UL-CCCH-MessageType',
                                   'UL-CCCH-MessageType-NB',
                                   'UL-DCCH-MessageType',
                                   'UL-DCCH-MessageType-NB',
                                   'SC-MCCH-MessageType-r13',
                                   'SC-MCCH-MessageType-NB',
                                   'BCCH-BCH-MessageType-TDD-NB-r1']
    rrc_items = {}
    with open(os.path.join(os.path.dirname(__file__), 'asn_standard', 'rrc.txt'), 'r') as f:
        message_type_data = f.read()
    sib_data = re.findall('SystemInformation(?:-NB)?\s*message\s*--\s*ASN1START(.*?)ASN1STOP', message_type_data, re.MULTILINE | re.DOTALL)
    sib_data = "".join(sib_data)
    # pprint.pprint(sib_data)
    # message_type_data = re.sub('\s3GPP\s3GPP.*?\)\s', "", message_type_data)
    message_type_data = re.findall('(?:EUTRA|NBIOT)-RRC-Definitions DEFINITIONS AUTOMATIC TAGS(.*?)6\.\d+\.\d+',
                                   message_type_data, re.MULTILINE | re.DOTALL)
    message_type_data = "".join(message_type_data)
    # print message_type_data
    message_type_data_lines = re.findall('(\S*MessageType\S*\s*::=.*?)\-\- ASN1STOP', message_type_data, re.DOTALL | re.MULTILINE)
    # pprint.pprint(message_type_data_lines)
    # check if all MessageTypes are parsed out from 3gpp
    for mtype in message_types_from_standard:
        found = False
        for message_type_data in message_type_data_lines:
            if mtype in message_type_data:
                found = True
                break
        assert found is True, 'no message_type_data for {}'.format(mtype)
    assert len(message_types_from_standard) == len(message_type_data_lines),\
        'length of parsed message_type_data does not match static message_types_from_standard length'
    for section in message_type_data_lines:
        if 'CHOICE' in section:
            # if 'UL-CCCH-MessageType' in item:
            #     print(item)
            # for all c1,c2... items
            # print item
            item = re.findall('c\d+\s*CHOICE\s*\{(.*?)\}', section, re.DOTALL | re.MULTILINE)
            # print(item)
            for sub_c_item in item:
                # pprint.pprint(sub_c_item)
                for subitem in sub_c_item.split(','):
                    subitem = re.findall('(\S+)', subitem)
                    # pprint.pprint(subitem)
                    if subitem[1] != 'NULL':
                        if subitem[0] in rrc_items:
                            # print('Trying to add: {}:{}, already exists {}:{}'.format(subitem[0], subitem[1], subitem[0], rrc_items[subitem[0]]))
                            mtype = get_mtype_in_section(message_types_from_standard, section)
                            # print('Found mtype: {}'.format(mtype))
                            m_type_suffix = get_message_type_suffix(mtype)
                            # print('Found mtype suffix: {}'.format(m_type_suffix))
                            new_subitem_0 = "{}-{}".format(subitem[0], m_type_suffix)
                            # print('Adding mtype_suffix: {} -> {} to differentiate'.format(subitem[0], new_subitem_0))
                            rrc_items[new_subitem_0] = subitem[1]

                        else:
                            rrc_items[subitem[0]] = subitem[1]
        else:
            # for MasterInformationBlock\S*
            # print item
            item = re.search('::=\s*(\S*)', section, re.DOTALL | re.MULTILINE).group(1)
            # print item
            rrc_items[item] = item
    sib_data_parsed = re.findall('OF CHOICE\s*\{(.*?)\}', sib_data, re.MULTILINE | re.DOTALL)
    # pprint.pprint(sib_data_parsed)
    for item in sib_data_parsed:
        item = re.sub(',\s*\.\.\.', '', item)
        item = re.sub('\[\[', '', item)
        item = re.sub('\]\]', '', item)
        # print(item)
        item = item.split(',')
        # item = re.findall('OF CHOICE \{(.*?)\}', item, re.DOTALL)[0].split(',')
        for subitem in item:
            # pprint.pprint(subitem)
            subitem = re.findall('(\S+)', subitem)
            # pprint.pprint(subitem)
            rrc_items[subitem[0]] = subitem[1]
    pprint.pprint("RRC Number of 3GPP compliant messages: {}".format(len(rrc_items)))
    # pprint.pprint(rrc_items)
    # pprint.pprint(rrc_non_3gpp_compliant_messages)
    pprint.pprint("RRC Number of non-compliant messages: {}".format(len(rrc_non_3gpp_compliant_messages)))
    rrc_items.update(rrc_non_3gpp_compliant_messages)
    # pprint.pprint(len(rrc_items))
    return rrc_items


def parse_ap_protocol(protocol_name):
    '''
    Parse AP family protocols e.g. S1AP, X2AP, M3AP

    :param protocol_name lower case
    :return: dict with mapping
    '''
    # print(protocol_name)
    with open(os.path.join(os.path.dirname(__file__), 'asn_standard', "%s.txt" % protocol_name), 'r') as open_file:
        data = open_file.read()
    proc_codes = re.findall('(id-\S+)\s*ProcedureCode\s*\:\:\=\s*(\d+)', data, re.MULTILINE | re.DOTALL)
    proc_codes = dict(proc_codes)
    # pprint.pprint(proc_codes)
    data = re.search('Interface Elementary Procedures.*?PDU Definitions', data, re.MULTILINE | re.DOTALL).group()
    asn_data = re.findall('(?:(?:INITIATING MESSAGE)|(?:SUCCESSFUL OUTCOME)|(?:UNSUCCESSFUL OUTCOME))\s+(\S+)', data, re.MULTILINE | re.DOTALL)
    asn_procedures = re.findall('AP-ELEMENTARY-PROCEDURE ::=\s*\{(.*?)\}', data, re.MULTILINE | re.DOTALL)
    ap_proc = {0: {}, 1: {}, 2: {}}
    for proc_msgs in asn_procedures:
        # print(proc_msgs)
        init = re.findall('INITIATING MESSAGE\s+(\S+)', proc_msgs)
        succ = re.findall('SUCCESSFUL OUTCOME\s+(\S+)', proc_msgs)
        unsucc = re.findall('UNSUCCESSFUL OUTCOME\s+(\S+)', proc_msgs)
        proc_code_id = re.findall('PROCEDURE CODE\s+(\S+)', proc_msgs)
        assert len(proc_code_id), 'PROCEDURE CODE must exist'
        procedure_code = int(proc_codes[proc_code_id[0]])
        # print(procedure_code)
        if len(init):
            ap_proc[0][int(procedure_code)] = init[0]
        if len(succ):
            ap_proc[1][int(procedure_code)] = succ[0]
        if len(unsucc):
            ap_proc[2][int(procedure_code)] = unsucc[0]

    # print protocol_name, len(asn_data)
    # pprint.pprint(ap_proc)
    ap_items = dict((item, item) for item in asn_data)
    # pprint.pprint(ap_items)
    return ap_items, ap_proc


def if_overwrite():
    u_input = raw_input('Do you want to overwrite? [<enter>=no, <yes,y>=yes]').strip().lower()
    if u_input in ['yes', 'y']:
        return True
    else:
        return False


message_types = {}
ap_procedure_types = {}
for protocol in supported_protocols:
    protocol_underscored = re.sub('-', '_', protocol)
    if 'ap' in protocol_underscored:
        types, procedures = parse_ap_protocol(protocol_underscored)
        ap_procedure_types[protocol_underscored] = procedures
    else:
        types = eval('parse_%s()' % protocol_underscored)
    message_types[protocol] = types

# pprint.pprint(message_types)
# pprint.pprint(ap_procedure_types)
if old_ms != message_types:
    print('message_types.py content differs, unlock overwriting')
    if if_overwrite():
        print('Writing new values to file message_types.py')
        with open('message_types.py', 'w') as out_file:
            out_file.write(python_header)
            out_file.write("\n\nsupported_protocols = " + pprint.pformat(supported_protocols) + "\n\n")
            out_file.write("message_types = {\n " + pprint.pformat(message_types, indent=1)[1:] + "\n")
            # for protocol in list(message_types_protocol.keys()):
            # out_file.write("%s = {\n " % protocol + pprint.pformat(message_types_protocol[protocol], indent=4)[1:] + "\n\n")
            # out_file.write("message_types = {\n " + pprint.pformat(message_types, indent=4)[1:]+"\n")
else:
    print('message_types.py content identical')

if old_ap_procedures != ap_procedure_types:
    print('ap_procedure_types.py content differs, unlock overwriting')
    if if_overwrite():
        print('Writing new values to file ap_procedure_types.py')
        with open('ap_procedure_types.py', 'w') as out_file:
            out_file.write(python_header)
            out_file.write("\n\nAP_PROCEDURE_TYPES = " + pprint.pformat(ap_procedure_types) + "\n")

else:
    print('ap_procedure_types.py content identical')
